// I31 and I35: every secret the realm file names is generated by platform/identity/setup.sh, named by
// .env.example and passed to the container; and setup.sh never changes a value an existing .env holds.
//
// setup.sh is run for real, from a copy in a temporary directory (it writes .env beside itself, so the live
// platform/identity/.env is never touched or read). It makes each value with `docker run <pinned node> node -e
// ...`; the check runs with no Docker and cannot execute a file it writes (its /tmp is noexec), so the copy is
// sourced by a shell that first defines a stand-in `docker` function, labelled as one. The stand-in answers
// `docker version` and runs the very command setup.sh hands to `docker run` with this process's own Node.
import assert from 'node:assert/strict'
import { spawnSync } from 'node:child_process'
import { copyFileSync, mkdirSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { dirname, join } from 'node:path'
import { test } from 'node:test'
import { fileURLToPath } from 'node:url'

const IDENTITY = fileURLToPath(new URL('..', import.meta.url))
const read = (relative: string): string => readFileSync(join(IDENTITY, relative), 'utf8')

const STAND_IN_DOCKER = `
# A stand-in for the docker CLI, defined by platform/identity/test/setup.test.ts for that test only. It answers
# "docker version", and for "docker run ... <pinned node image> <command...>" runs <command...> with the local Node.
docker() {
  case "$1" in
    version) echo 0.0.0-stand-in; return 0 ;;
    run)
      shift
      while [ "$#" -gt 0 ]; do
        case "$1" in
          node@sha256:*) shift; "$@"; return ;;
          *) shift ;;
        esac
      done
      echo "stand-in docker: the run command names no pinned Node image" >&2
      return 3 ;;
    *) echo "stand-in docker: unexpected command $1" >&2; return 3 ;;
  esac
}
`

type Run = { status: number | null; stderr: string; env: string | null }

/** Copies setup.sh and .env.example to a new directory, writes `existing` as its .env when given, and runs setup.sh there. */
function runSetup(existing: string | null): Run {
  const root = mkdtempSync(join(tmpdir(), 'identity-setup-'))
  try {
    const dir = join(root, 'identity')
    mkdirSync(dir)
    copyFileSync(join(IDENTITY, 'setup.sh'), join(dir, 'setup.sh'))
    copyFileSync(join(IDENTITY, '.env.example'), join(dir, '.env.example'))
    if (existing !== null) writeFileSync(join(dir, '.env'), existing, { mode: 0o600 })
    // sh -c '<stand-in>; . "$0"' <setup.sh>: $0 is the copy's path, which setup.sh reads to find its directory.
    const result = spawnSync('sh', ['-c', `${STAND_IN_DOCKER}\n. "$0"\n`, join(dir, 'setup.sh')], {
      env: { PATH: `${dirname(process.execPath)}:/usr/local/bin:/usr/bin:/bin` },
      encoding: 'utf8',
    })
    let env: string | null = null
    try {
      env = readFileSync(join(dir, '.env'), 'utf8')
    } catch {
      env = null
    }
    return { status: result.status, stderr: result.stderr, env }
  } finally {
    rmSync(root, { recursive: true, force: true })
  }
}

/** NAME=value lines of an env text. */
function values(text: string): Map<string, string> {
  const found = new Map<string, string>()
  for (const match of text.matchAll(/^([A-Z_][A-Z0-9_]*)=(.*)$/gm)) found.set(match[1] ?? '', match[2] ?? '')
  return found
}

const PLACEHOLDER = /^\$\{[A-Z][A-Z0-9_]*\}$/

test('I31. every ${...} in the realm file is generated by setup.sh, named by .env.example and passed to the container; no secret is a literal', () => {
  const realmText = read('realm/lab-realm.json')
  const placeholders = [...new Set([...realmText.matchAll(/\$\{([^}]*)\}/g)].map((match) => match[1] ?? ''))]
  assert.ok(placeholders.length >= 10, `the realm file names ${placeholders.length} placeholders`)

  // setup.sh, run where there is no .env, writes a value for each.
  const fresh = runSetup(null)
  assert.equal(fresh.status, 0, `setup.sh: exit ${String(fresh.status)}; ${fresh.stderr}`)
  assert.ok(fresh.env !== null, 'setup.sh wrote no .env')
  const written = values(fresh.env)
  for (const name of placeholders) {
    assert.match(name, /^[A-Z][A-Z0-9_]*$/, `the realm file holds \${${name}}, which is not a variable name`)
    assert.match(written.get(name) ?? '', /^[0-9a-f]{48,}$/, `setup.sh does not generate ${name}`)
  }

  const example = values(read('.env.example'))
  const compose = read('compose.yaml')
  for (const name of placeholders) {
    assert.ok(example.has(name), `.env.example does not name ${name}`)
    assert.match(compose, new RegExp(`^ {6}${name}: \\$\\{${name}:\\?run platform/identity/setup\\.sh\\}$`, 'm'), `compose.yaml does not pass ${name} to the container`)
  }

  // Every secret and credential value in the realm file, wherever it sits, is a placeholder.
  const literals: string[] = []
  const walk = (node: unknown, path: string): void => {
    if (Array.isArray(node)) node.forEach((entry, index) => walk(entry, `${path}[${index}]`))
    else if (typeof node === 'object' && node !== null) {
      for (const [key, value] of Object.entries(node)) {
        const here = `${path}.${key}`
        const isSecret = key === 'secret' || (key === 'value' && /\.credentials\[\d+\]$/.test(path))
        if (isSecret && !(typeof value === 'string' && PLACEHOLDER.test(value))) literals.push(here)
        walk(value, here)
      }
    }
  }
  walk(JSON.parse(realmText), '$')
  assert.deepEqual(literals, [], 'a secret or password in the realm file is not a ${NAME} placeholder')
})

test('I35. setup.sh, against a .env that holds the old names, changes no value in it and never reports success with a name missing', () => {
  // The five names platform/identity/.env held before this realm, with values in setup.sh's own formats.
  const old = [
    '# Written by platform/identity/setup.sh. Ignored by git; never commit it.',
    'IDENTITY_ADMIN_USERNAME=admin-0a1b2c3d',
    `IDENTITY_ADMIN_PASSWORD=${'a1'.repeat(24)}`,
    `IDENTITY_DESK_CLIENT_SECRET=${'d3'.repeat(32)}`,
    `IDENTITY_RILEY_PASSWORD=${'b2'.repeat(24)}`,
    `IDENTITY_DANA_PASSWORD=${'c4'.repeat(24)}`,
    '',
  ].join('\n')
  const oldValues = values(old)
  const run = runSetup(old)
  assert.ok(run.env !== null, 'setup.sh removed .env')

  // No value already there is changed.
  const after = values(run.env)
  for (const [name, value] of oldValues) assert.equal(after.get(name), value, `setup.sh changed ${name}`)
  // No value is printed.
  for (const value of oldValues.values()) assert.ok(!run.stderr.includes(value), 'setup.sh printed a value')

  // Every name .env.example names is now there, or setup.sh failed and named one that is not.
  const missing = [...values(read('.env.example')).keys()].filter((name) => (after.get(name) ?? '') === '')
  if (missing.length > 0) {
    assert.notEqual(run.status, 0, `setup.sh exited 0 with ${missing.join(', ')} missing`)
    assert.ok(missing.some((name) => run.stderr.includes(name)), `setup.sh did not name a missing variable: ${run.stderr}`)
  } else {
    assert.equal(run.status, 0, `setup.sh: exit ${String(run.status)}; ${run.stderr}`)
  }
})
